`,"Annotated air circuit breaker front view"),Tt=[y(1,70,90,40,40,e("Phase conductor","\u0645\u0648\u0635\u0644 \u0627\u0644\u0637\u0648\u0631"),e("Carries load current through the toroid. For 3-phase devices, all phases pass through it.","\u064A\u062D\u0645\u0644 \u062A\u064A\u0627\u0631 \u0627\u0644\u062D\u0645\u0644 \u0639\u0628\u0631 \u0627\u0644\u0642\u0644\u0628 \u0627\u0644\u062D\u0644\u0642\u064A. \u0648\u0641\u064A \u0627\u0644\u0623\u062C\u0647\u0632\u0629 \u062B\u0644\u0627\u062B\u064A\u0629 \u0627\u0644\u0623\u0637\u0648\u0627\u0631 \u062A\u0645\u0631 \u0643\u0644 \u0627\u0644\u0623\u0637\u0648\u0627\u0631 \u0639\u0628\u0631\u0647.")),y(2,70,150,40,200,e("Neutral conductor","\u0645\u0648\u0635\u0644 \u0627\u0644\u0646\u064A\u0648\u062A\u0631\u0627\u0644"),e("Must pass through the toroid; the sum of all currents must be zero in a healthy circuit.","\u064A\u062C\u0628 \u0623\u0646 \u064A\u0645\u0631 \u0639\u0628\u0631 \u0627\u0644\u0642\u0644\u0628\u061B \u0648\u0645\u062C\u0645\u0648\u0639 \u0643\u0644 \u0627\u0644\u062A\u064A\u0627\u0631\u0627\u062A \u0635\u0641\u0631 \u0641\u064A \u0627\u0644\u062F\u0627\u0626\u0631\u0629 \u0627\u0644\u0633\u0644\u064A\u0645\u0629.")),y(3,200,120,200,30,e("Toroidal transformer","\u0627\u0644\u0645\u062D\u0648\u0644 \u0627\u0644\u062D\u0644\u0642\u064A"),e("Summation CT: residual current induces a voltage in its secondary winding.","\u0645\u062D\u0648\u0644 \u062C\u0627\u0645\u0639: \u0627\u0644\u062A\u064A\u0627\u0631 \u0627\u0644\u0645\u062A\u0628\u0642\u064A \u064A\u062D\u062B \u062C\u0647\u062F\u064B\u0627 \u0641\u064A \u0645\u0644\u0641\u0647 \u0627\u0644\u062B\u0627\u0646\u0648\u064A.")),y(4,290,190,340,230,e("Sensitive release","\u0627\u0644\u0631\u064A\u0644\u064A\u0647 \u0627\u0644\u062D\u0633\u0627\u0633"),e("Polarised relay/electronics that trips the mechanism when residual current reaches I\u0394n.","\u0631\u064A\u0644\u064A\u0647 \u0645\u0633\u062A\u0642\u0637\u0628/\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A\u0627\u062A \u062A\u0641\u0635\u0644 \u0627\u0644\u0622\u0644\u064A\u0629 \u0639\u0646\u062F \u0628\u0644\u0648\u063A \u0627\u0644\u062A\u064A\u0627\u0631 \u0627\u0644\u0645\u062A\u0628\u0642\u064A I\u0394n.")),y(5,200,190,130,240,e("Test button","\u0632\u0631 \u0627\u0644\u0627\u062E\u062A\u0628\u0627\u0631"),e("Creates a known imbalance through a resistor to verify the device trips.","\u064A\u062E\u0644\u0642 \u0627\u062E\u062A\u0644\u0627\u0644\u064B\u0627 \u0645\u0639\u0644\u0648\u0645\u064B\u0627 \u0639\u0628\u0631 \u0645\u0642\u0627\u0648\u0645\u0629 \u0644\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0623\u0646 \u0627\u0644\u062C\u0647\u0627\u0632 \u064A\u0641\u0635\u0644.")),y(6,330,90,380,40,e("Contacts / mechanism","\u0627\u0644\u0645\u0644\u0627\u0645\u0633\u0627\u062A/\u0627\u0644\u0622\u0644\u064A\u0629"),e("Opens all poles, including the neutral.","\u064A\u0641\u062A\u062D \u062C\u0645\u064A\u0639 \u0627\u0644\u0623\u0642\u0637\u0627\u0628 \u0628\u0645\u0627 \u0641\u064A\u0647\u0627 \u0627\u0644\u0646\u064A\u0648\u062A\u0631\u0627\u0644."))],Pr=()=>q([420,280],`
