`,"RCCB schematic: toroid, release and test circuit"),Dt=[y(1,200,58,40,50,e("Fixed terminal / stem","\u0627\u0644\u0637\u0631\u0641 \u0627\u0644\u062B\u0627\u0628\u062A / \u0627\u0644\u0633\u0627\u0642"),e("Fixed conductor bringing current from the busbar side into the fixed contact.","\u0645\u0648\u0635\u0644 \u062B\u0627\u0628\u062A \u064A\u0648\u0635\u0644 \u0627\u0644\u062A\u064A\u0627\u0631 \u0645\u0646 \u062C\u0647\u0629 \u0627\u0644\u0642\u0636\u0628\u0627\u0646 \u0625\u0644\u0649 \u0627\u0644\u0645\u0644\u0627\u0645\u0633 \u0627\u0644\u062B\u0627\u0628\u062A.")),y(2,200,154,40,120,e("Fixed contact","\u0627\u0644\u0645\u0644\u0627\u0645\u0633 \u0627\u0644\u062B\u0627\u0628\u062A"),e("Stationary contact disc (typically a copper\u2013chromium alloy) that carries current when closed and takes the arc when opening.","\u0642\u0631\u0635 \u0645\u0644\u0627\u0645\u0633 \u062B\u0627\u0628\u062A (\u063A\u0627\u0644\u0628\u064B\u0627 \u0633\u0628\u064A\u0643\u0629 \u0646\u062D\u0627\u0633-\u0643\u0631\u0648\u0645) \u064A\u062D\u0645\u0644 \u0627\u0644\u062A\u064A\u0627\u0631 \u0639\u0646\u062F \u0627\u0644\u0625\u063A\u0644\u0627\u0642 \u0648\u064A\u062A\u062D\u0645\u0644 \u0627\u0644\u0642\u0648\u0633 \u0639\u0646\u062F \u0627\u0644\u0641\u062A\u062D.")),y(3,200,268,360,268,e("MOVING CONTACT","\u0627\u0644\u0645\u0644\u0627\u0645\u0633 \u0627\u0644\u0645\u062A\u062D\u0631\u0643"),e("Moves axially (millimetres of travel) to open/close the gap. It is driven by the breaker mechanism through the bellows-sealed stem. When the gap opens, a metal-vapour arc forms between the fixed and moving contacts.","\u064A\u062A\u062D\u0631\u0643 \u0645\u062D\u0648\u0631\u064A\u064B\u0627 (\u0645\u0633\u0627\u0641\u0629 \u0645\u0644\u0644\u064A\u0645\u062A\u0631\u0627\u062A) \u0644\u0641\u062A\u062D/\u063A\u0644\u0642 \u0627\u0644\u0641\u0627\u0635\u0644. \u062A\u062D\u0631\u0643\u0647 \u0622\u0644\u064A\u0629 \u0627\u0644\u0642\u0627\u0637\u0639 \u0639\u0628\u0631 \u0633\u0627\u0642 \u0645\u062D\u0643\u0645\u0629 \u0628\u0627\u0644\u0645\u0646\u0641\u0627\u062E. \u0648\u0639\u0646\u062F \u0641\u062A\u062D \u0627\u0644\u0641\u0627\u0635\u0644 \u064A\u062A\u0643\u0648\u0646 \u0642\u0648\u0633 \u0628\u062E\u0627\u0631 \u0645\u0639\u062F\u0646 \u0628\u064A\u0646 \u0627\u0644\u0645\u0644\u0627\u0645\u0633 \u0627\u0644\u062B\u0627\u0628\u062A \u0648\u0627\u0644\u0645\u062A\u062D\u0631\u0643.")),y(4,200,322,360,322,e("Bellows","\u0627\u0644\u0645\u0646\u0641\u0627\u062E"),e("Flexible stainless-steel bellows: lets the moving stem travel while keeping the vacuum sealed. Its mechanical life limits the number of operations.","\u0645\u0646\u0641\u0627\u062E \u0641\u0648\u0644\u0627\u0630\u064A \u0645\u0631\u0646: \u064A\u0633\u0645\u062D \u0628\u062D\u0631\u0643\u0629 \u0627\u0644\u0633\u0627\u0642 \u0645\u0639 \u0625\u062D\u0643\u0627\u0645 \u0627\u0644\u0641\u0631\u0627\u063A. \u0648\u0639\u0645\u0631\u0647 \u0627\u0644\u0645\u064A\u0643\u0627\u0646\u064A\u0643\u064A \u064A\u062D\u062F\u062F \u0639\u062F\u062F \u0627\u0644\u0639\u0645\u0644\u064A\u0627\u062A.")),y(5,157,210,40,210,e("Vapour shield","\u062F\u0631\u0639 \u0627\u0644\u0628\u062E\u0627\u0631"),e("Metal cylinder that condenses metal vapour and keeps it off the insulating envelope, preserving dielectric strength.","\u0623\u0633\u0637\u0648\u0627\u0646\u0629 \u0645\u0639\u062F\u0646\u064A\u0629 \u062A\u0643\u062B\u0641 \u0628\u062E\u0627\u0631 \u0627\u0644\u0645\u0639\u062F\u0646 \u0648\u062A\u0645\u0646\u0639\u0647 \u0645\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u063A\u0644\u0627\u0641 \u0627\u0644\u0639\u0627\u0632\u0644 \u0641\u062A\u062D\u0627\u0641\u0638 \u0639\u0644\u0649 \u0642\u0648\u0629 \u0627\u0644\u0639\u0632\u0644.")),y(6,142,270,40,290,e("Insulating envelope","\u0627\u0644\u063A\u0644\u0627\u0641 \u0627\u0644\u0639\u0627\u0632\u0644"),e("Ceramic (or other insulating) cylinder that holds the vacuum and insulates the two contact ends.","\u0623\u0633\u0637\u0648\u0627\u0646\u0629 \u062E\u0632\u0641\u064A\u0629 (\u0623\u0648 \u0639\u0627\u0632\u0644\u0629 \u0623\u062E\u0631\u0649) \u062A\u062D\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0644\u0641\u0631\u0627\u063A \u0648\u062A\u0639\u0632\u0644 \u0637\u0631\u0641\u064A \u0627\u0644\u0645\u0644\u0627\u0645\u0633\u0627\u062A.")),y(7,232,210,360,200,e("VACUUM","\u0627\u0644\u0641\u0631\u0627\u063A (VACUUM)"),e("Why vacuum works: with almost no gas molecules there is little to ionise, so once the current reaches zero the metal vapour condenses within microseconds and the gap recovers dielectric strength extremely fast. A short gap (millimetres) therefore withstands the transient recovery voltage. This gives short arcing time and low contact wear.","\u0644\u0645\u0627\u0630\u0627 \u064A\u0646\u062C\u062D \u0627\u0644\u0641\u0631\u0627\u063A: \u0628\u063A\u064A\u0627\u0628 \u0627\u0644\u062C\u0632\u064A\u0626\u0627\u062A \u0627\u0644\u063A\u0627\u0632\u064A\u0629 \u062A\u0642\u0631\u064A\u0628\u064B\u0627 \u0644\u0627 \u064A\u0648\u062C\u062F \u0645\u0627 \u064A\u062A\u0623\u064A\u0646\u060C \u0641\u0628\u0645\u062C\u0631\u062F \u0648\u0635\u0648\u0644 \u0627\u0644\u062A\u064A\u0627\u0631 \u0644\u0644\u0635\u0641\u0631 \u064A\u062A\u0643\u062B\u0641 \u0628\u062E\u0627\u0631 \u0627\u0644\u0645\u0639\u062F\u0646 \u062E\u0644\u0627\u0644 \u0645\u064A\u0643\u0631\u0648\u062B\u0648\u0627\u0646\u064D \u0648\u064A\u0633\u062A\u0639\u064A\u062F \u0627\u0644\u0641\u0627\u0635\u0644 \u0642\u0648\u062A\u0647 \u0627\u0644\u0639\u0627\u0632\u0644\u0629 \u0628\u0633\u0631\u0639\u0629 \u0647\u0627\u0626\u0644\u0629. \u0644\u0630\u0644\u0643 \u064A\u062A\u062D\u0645\u0644 \u0641\u0627\u0635\u0644 \u0642\u0635\u064A\u0631 (\u0645\u0644\u0644\u064A\u0645\u062A\u0631\u0627\u062A) \u062C\u0647\u062F \u0627\u0644\u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0627\u0644\u0639\u0627\u0628\u0631. \u0648\u0627\u0644\u0646\u062A\u064A\u062C\u0629 \u0632\u0645\u0646 \u0642\u0648\u0633 \u0642\u0635\u064A\u0631 \u0648\u062A\u0622\u0643\u0644 \u0645\u0644\u0627\u0645\u0633\u0627\u062A \u0642\u0644\u064A\u0644.")),y(8,200,210,40,160,e("Arc (metal vapour)","\u0627\u0644\u0642\u0648\u0633 (\u0628\u062E\u0627\u0631 \u0645\u0639\u062F\u0646)"),e("When contacts separate under current, a metal-vapour arc bridges the gap until current zero.","\u0639\u0646\u062F \u0627\u0646\u0641\u0635\u0627\u0644 \u0627\u0644\u0645\u0644\u0627\u0645\u0633\u0627\u062A \u062A\u062D\u062A \u062A\u064A\u0627\u0631 \u064A\u062C\u0633\u0631 \u0642\u0648\u0633 \u0628\u062E\u0627\u0631 \u0645\u0639\u062F\u0646 \u0627\u0644\u0641\u0627\u0635\u0644 \u062D\u062A\u0649 \u0635\u0641\u0631 \u0627\u0644\u062A\u064A\u0627\u0631.")),y(9,200,404,360,404,e("Insulating push rod","\u0642\u0636\u064A\u0628 \u0627\u0644\u062F\u0641\u0639 \u0627\u0644\u0639\u0627\u0632\u0644"),e("Insulated link between the live moving stem and the grounded operating mechanism.","\u0648\u0635\u0644\u0629 \u0639\u0627\u0632\u0644\u0629 \u0628\u064A\u0646 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0645\u062A\u062D\u0631\u0643\u0629 \u0627\u0644\u062D\u064A\u0629 \u0648\u0622\u0644\u064A\u0629 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u0645\u0624\u0631\u0636\u0629.")),y(10,200,106,360,70,e("End cap / seal","\u063A\u0637\u0627\u0621 \u0627\u0644\u0637\u0631\u0641 / \u0627\u0644\u0625\u062D\u0643\u0627\u0645"),e("Metal end flanges brazed to the ceramic to seal the vacuum.","\u0634\u0641\u062A\u0627\u0646 \u0645\u0639\u062F\u0646\u064A\u062A\u0627\u0646 \u0645\u0644\u062D\u0648\u0645\u062A\u0627\u0646 \u0628\u0627\u0644\u062E\u0632\u0641 \u0644\u0625\u062D\u0643\u0627\u0645 \u0627\u0644\u0641\u0631\u0627\u063A."))],Fr=()=>q([400,460],`
